sys_script.script:
(function executeRule(current, previous) {
    var checkOut = current.getValue('check_out');
    if (!checkOut) return;

    var workEnd = '';
    var earlyThreshold = 0;

    var empGr = new GlideRecord('x_2316161_bjit_e_0_emp');
    if (empGr.get(current.getValue('employee'))) {
        var empEnd = empGr.getValue('office_end');
        if (empEnd) {
            workEnd = empEnd;
            earlyThreshold = 30; // default threshold
        }
    }

    if (!workEnd) {
        var configGr = new GlideRecord('x_2316161_bjit_e_0_att_cfg');
        configGr.addQuery('active', true);
        configGr.setLimit(1);
        configGr.query();
        if (!configGr.next()) return;
        workEnd = configGr.getValue('work_end');
        earlyThreshold = parseInt(configGr.getValue('early_depart') || '0', 10);
    }

    if (workEnd) {
        var endParts = workEnd.split(':');
        var outParts = checkOut.split(':');
        var endMinutes = parseInt(endParts[0], 10) * 60 + parseInt(endParts[1], 10);
        var outMinutes = parseInt(outParts[0], 10) * 60 + parseInt(outParts[1], 10);
        current.setValue('is_early_dept', outMinutes < (endMinutes - earlyThreshold));
    }
})(current, previous);
